<?php include "db.php"; $msg=""; if(isset($_POST['login'])){$email=trim($_POST['email']);$password=$_POST['password'];$stmt=mysqli_prepare($conn,"SELECT id,name,password,role FROM users WHERE email=?");mysqli_stmt_bind_param($stmt,"s",$email);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);$u=mysqli_fetch_assoc($result);if($u&&password_verify($password,$u['password'])){$_SESSION['user_id']=$u['id'];$_SESSION['name']=$u['name'];$_SESSION['role']=$u['role'];header("Location: dashboard.php");exit();}else{$msg="Invalid email or password.";}} ?>
